R"VICTUSMSL(#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct Params
{
    float4 base_color;
    float4 uv_transform;
    float4 params;
    float4 screen;
};

struct main0_out
{
    float4 out_reactive [[color(0)]];
};

struct main0_in
{
    float2 v_uv [[user(locn2)]];
    float4 v_color [[user(locn4)]];
};

fragment main0_out main0(main0_in in [[stage_in]], constant Params& u [[buffer(0)]], texture2d<float> u_base_color [[texture(0)]], texture2d<float> u_depth [[texture(1)]], sampler u_base_colorSmplr [[sampler(0)]], sampler u_depthSmplr [[sampler(1)]], float4 gl_FragCoord [[position]])
{
    main0_out out = {};
    float2 suv = gl_FragCoord.xy * u.screen.xy;
    if (gl_FragCoord.z > u_depth.sample(u_depthSmplr, suv, level(0.0)).x)
    {
        discard_fragment();
    }
    float4 base = u_base_color.sample(u_base_colorSmplr, ((in.v_uv * u.uv_transform.xy) + u.uv_transform.zw)) * u.base_color;
    float _74;
    if (u.params.z > 0.5)
    {
        _74 = base.w;
    }
    else
    {
        _74 = base.w * in.v_color.w;
    }
    float coverage = _74;
    if (coverage < u.params.y)
    {
        discard_fragment();
    }
    if (u.params.w > 0.5)
    {
        coverage *= fast::min(dot(base.xyz * in.v_color.xyz, float3(0.2125999927520751953125, 0.715200006961822509765625, 0.072200000286102294921875)) * 4.0, 1.0);
    }
    coverage = fast::clamp(coverage, 0.0, 1.0);
    if (coverage <= 0.0)
    {
        discard_fragment();
    }
    float r = fast::clamp(u.params.x, 0.0, 1.0);
    out.out_reactive = float4(r, r, r, coverage);
    return out;
}

)VICTUSMSL";
